function isPasswordLikeNavigationLabel(value: string | undefined) {
  return /парол|password|passwort|contrase|mot de passe|senha|jelsz|şifre|sandi|wachtwoord|lösenord|كلمة المرور/i.test(value || "");
}

function localizedNavigationNextCopy(code: AppLocaleCode, target: Partial<Record<string, string>>, terms: Record<string, string>) {
  const candidate = target.next;
  if (candidate && !isPasswordLikeNavigationLabel(candidate)) return candidate;
  return navigationNextFallbacks[code] || navigationNextFallbacks.en || terms.open;
}

function localizedFallbackForEnglishCopy(code: AppLocaleCode, key: string): string {
  const terms = derivedUiTerms[code];
  const target = localeOverrides[code] || {};
  if (key === "cancel" || key.endsWith("_cancel")) return cancelFallbacks[code] || cancelFallbacks.en;
  if (!terms) return en[key] || key;
  const keyLabel = readableKeyLabel(key);
  if (key === "pay_yookassa_choose" || key === "pay_sbp") {
    return paymentMethodCopyFallbacks[code]?.[key] || paymentMethodCopyFallbacks.en[key];
  }
  if (key === "payment_options") {
    return target.payment_options && target.payment_options !== en.payment_options ? target.payment_options : target.premium || terms.account;
  }
  const viewMatch = /^view_(.+)_(kicker|title|subtitle|action)$/.exec(key);
  if (viewMatch) {
    const view = viewMatch[1];
    const label =
      target[view] ||
      target[view.replace("leaderboard", "leaders")] ||
      target[view.replace("referral", "referrals")] ||
      target[view.replace("level", "level_test")] ||
      target[view.replace("words", "learn_words")] ||
      target[view.replace("word_game", "word_game")] ||
      terms.section;
    if (viewMatch[2] === "kicker") return terms.section;
    if (viewMatch[2] === "title") return label;
    if (viewMatch[2] === "action") return `${terms.open}: ${label}`;
    return `${terms.workspace}: ${label}`;
  }
  const navMatch = /^nav_(.+)_desc$/.exec(key);
  if (navMatch) {
    const label =
      target[navMatch[1]] ||
      target[navMatch[1].replace("leaderboard", "leaders")] ||
      target[navMatch[1].replace("referral", "referrals")] ||
      target[navMatch[1].replace("level", "level_test")] ||
      terms.section;
    return `${label}: ${terms.section}`;
  }
  if (key.startsWith("auth_error_")) return target.auth_failed && target.auth_failed !== en.auth_failed ? target.auth_failed : terms.unavailable;
  if (key === "auth_failed") return terms.unavailable;
  if (key.startsWith("auth_")) return target.auth_failed && /failed|auth/i.test(keyLabel) ? terms.unavailable : `${target.account || terms.account}: ${keyLabel}`;
  if (key.includes("phrasebook") || key.includes("note")) return target.phrasebook || terms.words;
  if (key.includes("bug") || key.includes("report") || key.includes("screenshot") || key.includes("problem")) {
    if (key.includes("send")) return target.send || terms.open;
    if (key.includes("close")) return terms.open;
    if (key.includes("attach") || key.includes("image")) return target.tools || terms.open;
    if (key.includes("sent") || key.includes("saved")) return terms.ready;
    return target.tools || terms.unavailable;
  }
  if (key.includes("payment") || key.includes("crypto") || key.includes("network")) return target.payment_options && target.payment_options !== en.payment_options ? target.payment_options : target.premium || terms.account;
  if (key.includes("activity") || key.includes("rhythm") || key.includes("training_balance")) return target.dashboard || terms.growth;
  if (key.includes("learned") || key.includes("completed") || key.includes("rounds") || key.includes("attempts") || key.includes("repaired") || key.includes("practiced")) return target.dashboard || terms.growth;
  if (key.includes("lesson")) return target.new_lesson || terms.learn;
  if (key.includes("language")) return target.interface_language || target.languages || terms.learn;
  if (key.includes("practice")) return target.practice || terms.learn;
  if (key.includes("today") || key.includes("daily") || key.includes("habit")) return target.today || terms.daily;
  if (key.includes("weekly") || key.includes("plan")) return target.dashboard || terms.growth;
  if (key.includes("roleplay")) return target.roleplay || terms.learn;
  if (key.includes("pronunciation")) return target.pronunciation || terms.learn;
  if (key.includes("spelling")) return target.spelling || terms.words;
  if (key.includes("offline")) return target.offline_decks || terms.words;
  if (key.includes("dashboard")) return target.dashboard || terms.growth;
  if (key.includes("word") || key.includes("vocab")) return target.learn_words || terms.words;
  if (key.includes("card")) return target.offline_decks || terms.words;
  if (key.includes("mistake")) return target.mistakes || terms.words;
  if (key.includes("premium")) return target.premium || terms.account;
  if (key.includes("referral") || key.includes("invite")) return target.referrals || terms.account;
  if (key.includes("setting") || key.includes("account") || key.includes("telegram")) return target.settings || terms.account;
  if (key.includes("level") || key.includes("score") || key.includes("progress")) return target.progress || terms.growth;
  if (key.includes("listen") || key.includes("shadowing") || key.includes("voice")) return target.shadowing || terms.learn;
  if (key.includes("tool") || key.includes("translate") || key.includes("image")) return target.tools || terms.learn;
  if (key.includes("send")) return target.send || terms.open;
  if (key.includes("start") || key.includes("open") || key.includes("load")) return terms.open;
  if (key.includes("back")) return target.back || terms.open;
  if (key.includes("next")) return localizedNavigationNextCopy(code, target, terms);
  if (key.includes("clear") || key.includes("remove")) return target.clear || terms.open;
  if (key.includes("ready") || key.includes("done") || key.includes("available")) return terms.ready;
  if (key.includes("failed") || key.includes("unavailable")) return terms.unavailable;
  return terms.section;
}

appLocaleCodes.forEach((code) => {
  if (code === "en") return;
  const target = localeOverrides[code] || {};
  Object.keys(en).forEach((key) => {
    if (key === "skip") return;
    if (target[key] === en[key]) target[key] = localizedFallbackForEnglishCopy(code, key);
  });
  localeOverrides[code] = target;
});

