Object.entries(cleanV2ManualOverrides).forEach(([locale, values]) => {
  const code = locale as AppLocaleCode;
  localeOverrides[code] = { ...(localeOverrides[code] || {}), ...values };
});

appLocaleCodes.forEach((code) => {
  if (code === "en") return;
  const terms = derivedUiTerms[code];
  if (!terms) return;
  const target = localeOverrides[code] || {};
  const generic = {
    progress: target.progress || terms.growth,
    phrasebook_title: target.phrasebook || terms.words,
    phrasebook_body: target.phrasebook || terms.words,
    phrasebook_phrase_placeholder: target.phrasebook || terms.words,
    phrasebook_note_placeholder: target.phrasebook || terms.words,
    dashboard_learning_body: target.dashboard || terms.growth,
    learning_activity: target.dashboard || terms.growth,
    progress_without_leaderboard: target.dashboard || terms.growth,
    activity: target.today || terms.daily,
    weekly_rhythm: target.dashboard || terms.growth,
    training_balance: target.dashboard || terms.growth,
    words_learned: target.learn_words || terms.words,
    phrases_practiced: target.practice || terms.learn,
    lessons_completed: target.new_lesson || terms.learn,
    review_rounds: target.word_game || terms.words,
    voice_attempts: target.shadowing || terms.learn,
    mistakes_repaired: target.mistakes || terms.words,
    payment_options: target.payment_options && target.payment_options !== en.payment_options ? target.payment_options : target.premium || terms.account,
    payment_requisites: target.payment_options || target.premium || terms.account,
    check_payment: target.payment_options || target.premium || terms.account,
    specified_network: target.payment_options || target.premium || terms.account,
    premium_year_title: target.premium || "Premium",
    premium_year_body: target.premium || "365 days",
    payment_crypto_instruction: target.payment_options || target.premium || terms.account,
  };
  Object.entries(generic).forEach(([key, value]) => {
    const current = String(target[key] || "").trim();
    if (!current || current === en[key] || /^[^\s:]+:\s*[a-z0-9_ -]+$/i.test(current) || /^(Section|Раздел|Mục):\s*/i.test(current) || /Ð|Ñ|Гђ|Г‘|б»|бє|бї|аё|а№|а¤|аҐ|а¦|а§|а®|а°/u.test(current)) target[key] = value;
  });
  localeOverrides[code] = target;
});

