  ro: { stars: "Plata Telegram Stars se deschide în Telegram. Finalizează factura în bot; Premium se activează automat.", cryptoPrepare: "Alege rețeaua crypto și copiază suma exactă, portofelul, rețeaua și comentariul. Nu rotunji suma.", crypto: "Transferă exact {amount}. Folosește rețeaua afișată: {network}. Altă sumă sau rețea poate să nu fie creditată automat.", trc20: "Trimite exact {amount} ca USDT TRC20 prin rețeaua Tron. Dacă suma sau rețeaua diferă, plata poate să nu apară automat.", shownAmount: "suma afișată" },
  pt: { stars: "O pagamento Telegram Stars abre no Telegram. Conclua a fatura no bot; o Premium será ativado automaticamente.", cryptoPrepare: "Escolha a rede cripto e copie o valor exato, carteira, rede e comentário. Não arredonde o valor.", crypto: "Transfira exatamente {amount}. Use a rede mostrada: {network}. Outro valor ou rede pode não ser creditado automaticamente.", trc20: "Envie exatamente {amount} em USDT TRC20 pela rede Tron. Se o valor ou a rede forem diferentes, o pagamento pode não aparecer automaticamente.", shownAmount: "o valor mostrado" },
