  te: { stars: "Telegram Stars చెల్లింపు Telegram లో తెరుస్తుంది. bot లో invoice పూర్తి చేయండి; Premium స్వయంగా ఆన్ అవుతుంది.", cryptoPrepare: "crypto network ఎంచుకుని ఖచ్చితమైన మొత్తం, wallet, network, comment కాపీ చేయండి. మొత్తాన్ని round చేయవద్దు.", crypto: "ఖచ్చితంగా {amount} పంపండి. చూపిన network వాడండి: {network}. వేరే మొత్తం లేదా network స్వయంగా credit కాకపోవచ్చు.", trc20: "Tron network లో ఖచ్చితంగా {amount} USDT TRC20 పంపండి. మొత్తం లేదా network వేరైతే చెల్లింపు స్వయంగా కనిపించకపోవచ్చు.", shownAmount: "చూపిన మొత్తం" },
