  tl: { stars: "Magbubukas ang Telegram Stars payment sa Telegram. Tapusin ang invoice sa bot; awtomatikong maa-activate ang Premium.", cryptoPrepare: "Pumili ng crypto network at kopyahin ang eksaktong halaga, wallet, network, at comment. Huwag i-round ang halaga.", crypto: "Magpadala ng eksaktong {amount}. Gamitin ang ipinakitang network: {network}. Ibang halaga o network ay maaaring hindi ma-credit awtomatiko.", trc20: "Magpadala ng eksaktong {amount} bilang USDT TRC20 sa Tron network. Kung iba ang halaga o network, maaaring hindi lumitaw awtomatiko ang bayad.", shownAmount: "ipinakitang halaga" },
  tr: { stars: "Telegram Stars ödemesi Telegram'da açılır. Faturayı botta tamamlayın; Premium otomatik etkinleşir.", cryptoPrepare: "Kripto ağı seçin; tam tutarı, cüzdanı, ağı ve yorumu kopyalayın. Tutarı yuvarlamayın.", crypto: "Tam olarak {amount} gönderin. Gösterilen ağı kullanın: {network}. Farklı tutar veya ağ otomatik işlenmeyebilir.", trc20: "Tron ağında tam olarak {amount} USDT TRC20 gönderin. Tutar veya ağ farklıysa ödeme otomatik görünmeyebilir.", shownAmount: "gösterilen tutar" },
