const studyPlanCopy: Record<AppLocaleCode, { title: string; active: string; steady: string; words: string; speak: string; listen: string; repair: string }> = {
  ru: { title: "План обучения на сегодня", active: "Сначала закрываем одну ошибку, потом короткий цикл слова -> фраза -> аудирование, чтобы новые темы не наслаивались на старые пробелы.", steady: "Держим ритм: слова для разогрева, фразы для вывода, аудирование для слуха и один быстрый контроль.", words: "5 слов текущего уровня, пример и быстрый повтор только сложных.", speak: "3 полезные фразы под реальные ситуации, одну сохраните в заметки.", listen: "Одна короткая аудиофраза: послушать, повторить, исправить слабый звук.", repair: "Одна ошибка или spelling-пробел закрывается до новых материалов." },
  en: { title: "Focused study plan", active: "Close one mistake first, then run a short word -> phrase -> listening loop so new topics do not pile up over weak spots.", steady: "Keep a clean rhythm: words to warm up, phrases for output, listening for the ear, and one quick check.", words: "5 current-level words with an example and a quick review of only the difficult ones.", speak: "3 useful phrases for real situations; save the strongest one to notes.", listen: "One short audio phrase: listen, repeat, then fix the weakest sound.", repair: "Close one mistake or spelling gap before adding new material." },
  es: { title: "Plan de estudio de hoy", active: "Cierra primero un error y luego haz un ciclo breve: palabra -> frase -> escucha, para que los temas nuevos no tapen huecos antiguos.", steady: "Mantén el ritmo: palabras para calentar, frases para producir, escucha para el oído y una revisión rápida.", words: "5 palabras de tu nivel con ejemplo y repaso rápido solo de las difíciles.", speak: "3 frases útiles para situaciones reales; guarda la mejor en notas.", listen: "Una frase de audio corta: escucha, repite y corrige el sonido más débil.", repair: "Cierra un error o hueco de ortografía antes de añadir material nuevo." },
  de: { title: "Lernplan für heute", active: "Schließe zuerst einen Fehler, dann folgt kurz Wort -> Satz -> Hören, damit neue Themen keine alten Lücken überdecken.", steady: "Halte den Rhythmus: Wörter zum Aufwärmen, Sätze zum Sprechen, Hören fürs Ohr und ein schneller Check.", words: "5 Wörter auf deinem Niveau mit Beispiel und kurzer Wiederholung nur der schwierigen.", speak: "3 nützliche Sätze für echte Situationen; speichere den stärksten in Notizen.", listen: "Eine kurze Audio-Phrase: hören, wiederholen, den schwächsten Laut korrigieren.", repair: "Schließe einen Fehler oder eine Rechtschreiblücke vor neuem Material." },
  fr: { title: "Plan d'étude du jour", active: "Corrige d'abord une erreur, puis enchaîne mot -> phrase -> écoute pour éviter d'empiler du nouveau sur d'anciens manques.", steady: "Garde le rythme: mots pour démarrer, phrases pour produire, écoute pour l'oreille et un contrôle rapide.", words: "5 mots de ton niveau avec exemple et rappel rapide seulement des plus difficiles.", speak: "3 phrases utiles pour des situations réelles; garde la meilleure en notes.", listen: "Une courte phrase audio: écouter, répéter, corriger le son le plus faible.", repair: "Corrige une erreur ou un trou d'orthographe avant d'ajouter du nouveau." },
  it: { title: "Piano di studio di oggi", active: "Chiudi prima un errore, poi fai il ciclo parola -> frase -> ascolto, così i temi nuovi non coprono lacune vecchie.", steady: "Mantieni il ritmo: parole per scaldarti, frasi per parlare, ascolto per l'orecchio e un controllo rapido.", words: "5 parole del livello attuale con esempio e ripasso rapido solo di quelle difficili.", speak: "3 frasi utili per situazioni reali; salva la migliore nelle note.", listen: "Una breve frase audio: ascolta, ripeti e correggi il suono più debole.", repair: "Chiudi un errore o una lacuna di spelling prima di nuovo materiale." },
  zh: { title: "今日学习计划", active: "先修正一个错误，再完成词汇 -> 句子 -> 听力的小循环，避免新内容压在旧漏洞上。", steady: "保持节奏：词汇热身、短句输出、听力训练，再做一次快速检查。", words: "学习5个当前级别词汇，配例句，只复习困难项。", speak: "练3个真实场景短句，把最有用的一句存入笔记。", listen: "听一条短音频，跟读，并修正最薄弱的发音。", repair: "先补一个错误或拼写漏洞，再进入新内容。" },
  ja: { title: "今日の学習プラン", active: "まずミスを1つ直し、その後で単語 -> フレーズ -> リスニングの短い流れに進みます。", steady: "単語で準備し、フレーズで出力し、リスニングで耳を作り、最後に短く確認します。", words: "今のレベルの単語を5つ、例文つきで学び、難しいものだけ復習します。", speak: "実際の場面で使う短いフレーズを3つ作り、1つをノートに残します。", listen: "短い音声を1つ聞いて、まねして、弱い音を直します。", repair: "新しい内容に入る前に、ミスかスペルの穴を1つ埋めます。" },
  ko: { title: "오늘의 학습 계획", active: "먼저 실수 하나를 고친 뒤 단어 -> 문장 -> 듣기 순서로 짧게 반복합니다.", steady: "단어로 워밍업하고, 문장으로 말하고, 듣기로 귀를 열고, 마지막에 빠르게 점검합니다.", words: "현재 수준의 단어 5개를 예문과 함께 보고 어려운 것만 빠르게 복습합니다.", speak: "실제 상황에 쓸 표현 3개를 만들고 가장 좋은 하나를 노트에 저장합니다.", listen: "짧은 오디오 문장 하나를 듣고 따라 말한 뒤 약한 소리를 고칩니다.", repair: "새 자료 전에 실수나 철자 빈틈 하나를 먼저 닫습니다." },
  tg: { title: "Нақшаи омӯзиши имрӯз", active: "Аввал як хаторо ислоҳ кунед, баъд занҷири кӯтоҳи калима -> ҷумла -> шуниданро гузаред.", steady: "Ритмро нигоҳ доред: калимаҳо барои гармшавӣ, ҷумлаҳо барои гуфтан, шунидан барои гӯш ва санҷиши зуд.", words: "5 калимаи сатҳи ҷорӣ бо мисол ва такрори зуд танҳо барои душворҳо.", speak: "3 ҷумлаи муфид барои ҳолатҳои воқеӣ; беҳтаринашро дар қайдҳо нигоҳ доред.", listen: "Як аудиои кӯтоҳ: гӯш кунед, такрор кунед ва садои заифро ислоҳ намоед.", repair: "Пеш аз маводи нав як хато ё камбуди имлоро пӯшед." },
  uz: { title: "Bugungi o'quv rejasi", active: "Avval bitta xatoni yoping, keyin so'z -> ibora -> tinglash qisqa siklini bajaring.", steady: "Ritmni saqlang: so'zlar bilan qizish, iboralar bilan gapirish, tinglash va tez tekshiruv.", words: "Joriy darajadagi 5 so'z, misol va faqat qiyinlarini tez takrorlash.", speak: "Real vaziyatlar uchun 3 foydali ibora; eng yaxshisini eslatmaga saqlang.", listen: "Bitta qisqa audio ibora: tinglang, takrorlang va zaif tovushni tuzating.", repair: "Yangi materialdan oldin bitta xato yoki imlo bo'shlig'ini yoping." },
  tt: { title: "Бүгенге уку планы", active: "Башта бер хатаны төзәтегез, аннары сүз -> фраза -> тыңлау кыска циклын эшләгез.", steady: "Ритмны саклагыз: сүзләр белән җылынып алу, фразалар белән сөйләү, тыңлау һәм тиз тикшерү.", words: "Хәзерге дәрәҗәдән 5 сүз, мисал һәм авырларын гына тиз кабатлау.", speak: "Чын хәлләр өчен 3 файдалы фраза; иң яхшысын искәрмәләргә саклагыз.", listen: "Бер кыска аудиофраза: тыңлагыз, кабатлагыз, зәгыйфь авазны төзәтегез.", repair: "Яңа материалга кадәр бер хата яки spelling бушлыгын ябыгыз." },
  hy: { title: "Այսօրվա ուսուցման պլան", active: "Սկզբում փակեք մեկ սխալ, հետո անցեք կարճ շրջանով՝ բառ -> արտահայտություն -> լսում։", steady: "Պահեք ռիթմը՝ բառեր տաքացման համար, արտահայտություններ խոսելու համար, լսում և արագ ստուգում։", words: "Ընթացիկ մակարդակի 5 բառ՝ օրինակով և միայն դժվարների արագ կրկնությամբ։", speak: "3 օգտակար արտահայտություն իրական իրավիճակների համար, լավագույնը պահեք նշումներում։", listen: "Մեկ կարճ աուդիո արտահայտություն՝ լսել, կրկնել և շտկել թույլ հնչյունը։", repair: "Նոր նյութից առաջ փակեք մեկ սխալ կամ ուղղագրական բաց։" },
  kk: { title: "Бүгінгі оқу жоспары", active: "Алдымен бір қатені жабыңыз, кейін сөз -> фраза -> тыңдау қысқа циклын орындаңыз.", steady: "Ырғақты сақтаңыз: сөздермен қызыну, фразамен сөйлеу, тыңдау және бір жылдам тексеріс.", words: "Қазіргі деңгейден 5 сөз, мысал және тек қиындарын қысқа қайталау.", speak: "Нақты жағдайға арналған 3 пайдалы фраза; ең жақсысын жазбаға сақтаңыз.", listen: "Бір қысқа аудиофраза: тыңдау, қайталау, әлсіз дыбысты түзету.", repair: "Жаңа материалға дейін бір қате немесе spelling бос орнын жабыңыз." },
  ky: { title: "Бүгүнкү окуу планы", active: "Адегенде бир катаны жабыңыз, андан соң сөз -> фраза -> угуу кыска циклин өтүңүз.", steady: "Ыргакты кармаңыз: сөздөр менен даярдануу, фразалар менен сүйлөө, угуу жана тез текшерүү.", words: "Учурдагы деңгээлден 5 сөз, мисал жана кыйындарын гана тез кайталоо.", speak: "Чыныгы жагдайлар үчүн 3 пайдалуу фраза; эң жакшыны эскертмеге сактаңыз.", listen: "Бир кыска аудиофраза: угуу, кайталоо жана алсыз үндү оңдоо.", repair: "Жаңы материалдан мурун бир ката же spelling боштугун жабыңыз." },
  ka: { title: "დღევანდელი სასწავლო გეგმა", active: "ჯერ დახურეთ ერთი შეცდომა, შემდეგ გაიარეთ მოკლე ციკლი: სიტყვა -> ფრაზა -> მოსმენა.", steady: "შეინარჩუნეთ რიტმი: სიტყვები გასახურებლად, ფრაზები საუბრისთვის, მოსმენა და ერთი სწრაფი შემოწმება.", words: "მიმდინარე დონის 5 სიტყვა მაგალითით და სწრაფი გამეორება მხოლოდ რთულებისთვის.", speak: "3 სასარგებლო ფრაზა რეალური სიტუაციებისთვის; საუკეთესო შეინახეთ ჩანაწერებში.", listen: "ერთი მოკლე აუდიოფრაზა: მოუსმინეთ, გაიმეორეთ და შეასწორეთ სუსტი ბგერა.", repair: "ახალ მასალამდე დახურეთ ერთი შეცდომა ან spelling-ხარვეზი." },
  uk: { title: "План навчання на сьогодні", active: "Спершу закрийте одну помилку, потім пройдіть короткий цикл слово -> фраза -> аудіювання.", steady: "Тримайте ритм: слова для розігріву, фрази для мовлення, аудіювання і швидка перевірка.", words: "5 слів поточного рівня з прикладом і швидке повторення лише складних.", speak: "3 корисні фрази для реальних ситуацій; найкращу збережіть у нотатки.", listen: "Одна коротка аудіофраза: послухати, повторити й виправити слабкий звук.", repair: "Перед новим матеріалом закрийте одну помилку або spelling-прогалину." },
  pl: { title: "Dzisiejszy plan nauki", active: "Najpierw zamknij jeden błąd, potem przejdź krótki cykl: słowo -> fraza -> słuchanie.", steady: "Trzymaj rytm: słowa na rozgrzewkę, frazy do mówienia, słuchanie i szybki test.", words: "5 słów z obecnego poziomu z przykładem i szybka powtórka tylko trudnych.", speak: "3 użyteczne frazy do realnych sytuacji; najlepszą zapisz w notatkach.", listen: "Jedna krótka fraza audio: posłuchaj, powtórz i popraw najsłabszy dźwięk.", repair: "Przed nowym materiałem zamknij jeden błąd lub lukę w pisowni." },
  ro: { title: "Planul de studiu de azi", active: "Închide mai întâi o greșeală, apoi parcurge ciclul scurt cuvânt -> frază -> ascultare.", steady: "Păstrează ritmul: cuvinte pentru încălzire, fraze pentru vorbire, ascultare și o verificare rapidă.", words: "5 cuvinte de nivel curent, cu exemplu și recapitulare rapidă doar pentru cele dificile.", speak: "3 fraze utile pentru situații reale; salvează cea mai bună în notițe.", listen: "O frază audio scurtă: ascultă, repetă și corectează sunetul slab.", repair: "Înainte de material nou, închide o greșeală sau o lacună de spelling." },
  pt: { title: "Plano de estudo de hoje", active: "Feche primeiro um erro, depois faça o ciclo curto palavra -> frase -> escuta.", steady: "Mantenha o ritmo: palavras para aquecer, frases para falar, escuta e uma checagem rápida.", words: "5 palavras do nível atual com exemplo e revisão rápida só das difíceis.", speak: "3 frases úteis para situações reais; salve a melhor nas notas.", listen: "Uma frase curta de áudio: ouvir, repetir e corrigir o som mais fraco.", repair: "Antes de material novo, feche um erro ou lacuna de spelling." },
  ar: { title: "خطة التعلم اليوم", active: "أغلق خطأ واحداً أولاً، ثم نفذ دورة قصيرة: كلمة -> عبارة -> استماع.", steady: "حافظ على الإيقاع: كلمات للإحماء، عبارات للكلام، استماع، ثم فحص سريع.", words: "5 كلمات من مستواك مع مثال ومراجعة سريعة للصعب فقط.", speak: "3 عبارات مفيدة لمواقف حقيقية؛ احفظ الأفضل في الملاحظات.", listen: "عبارة صوتية قصيرة: استمع، كرر، ثم أصلح أضعف صوت.", repair: "أغلق خطأ أو فجوة إملائية واحدة قبل إضافة مادة جديدة." },
  bn: { title: "আজকের শেখার পরিকল্পনা", active: "আগে একটি ভুল ঠিক করুন, তারপর ছোট চক্র করুন: শব্দ -> বাক্যাংশ -> শোনা।", steady: "ছন্দ রাখুন: ওয়ার্ম-আপে শব্দ, বলার জন্য বাক্যাংশ, কানের জন্য শোনা, তারপর দ্রুত চেক।", words: "বর্তমান স্তরের ৫টি শব্দ, উদাহরণসহ, শুধু কঠিনগুলো দ্রুত পুনরাবৃত্তি।", speak: "বাস্তব পরিস্থিতির জন্য ৩টি দরকারি বাক্যাংশ; সেরা একটি নোটে রাখুন।", listen: "একটি ছোট অডিও বাক্যাংশ: শুনুন, повтор করুন, দুর্বল ধ্বনি ঠিক করুন।", repair: "নতুন উপকরণের আগে একটি ভুল বা spelling ফাঁক বন্ধ করুন।" },
  cs: { title: "Dnešní studijní plán", active: "Nejdřív uzavři jednu chybu, potom krátký cyklus slovo -> fráze -> poslech.", steady: "Drž rytmus: slova na rozehřátí, fráze k mluvení, poslech a rychlá kontrola.", words: "5 slov aktuální úrovně s příkladem a rychlé opakování jen těžkých.", speak: "3 užitečné fráze pro reálné situace; nejlepší ulož do poznámek.", listen: "Jedna krátká audio fráze: poslechni, zopakuj a oprav nejslabší zvuk.", repair: "Před novým materiálem uzavři jednu chybu nebo mezeru v pravopisu." },
  el: { title: "Σημερινό πλάνο μάθησης", active: "Κλείσε πρώτα ένα λάθος και μετά κάνε τον σύντομο κύκλο λέξη -> φράση -> ακρόαση.", steady: "Κράτα ρυθμό: λέξεις για ζέσταμα, φράσεις για ομιλία, ακρόαση και γρήγορο έλεγχο.", words: "5 λέξεις του τρέχοντος επιπέδου με παράδειγμα και γρήγορη επανάληψη μόνο των δύσκολων.", speak: "3 χρήσιμες φράσεις για πραγματικές καταστάσεις· κράτησε την καλύτερη στις σημειώσεις.", listen: "Μία σύντομη ηχητική φράση: άκου, επανάλαβε και διόρθωσε τον αδύναμο ήχο.", repair: "Πριν από νέο υλικό, κλείσε ένα λάθος ή κενό spelling." },
  hi: { title: "आज की सीखने की योजना", active: "पहले एक गलती ठीक करें, फिर छोटा क्रम करें: शब्द -> वाक्यांश -> सुनना।", steady: "लय बनाए रखें: शब्दों से वार्म-अप, वाक्यांशों से बोलना, सुनना और एक तेज जांच।", words: "मौजूदा स्तर के 5 शब्द, उदाहरण के साथ, और सिर्फ कठिन शब्दों की तेज पुनरावृत्ति।", speak: "असल स्थितियों के लिए 3 उपयोगी वाक्यांश; सबसे अच्छा नोट्स में सेव करें।", listen: "एक छोटा ऑडियो वाक्यांश: सुनें, दोहराएं और कमजोर ध्वनि सुधारें।", repair: "नए पाठ से पहले एक गलती या spelling gap बंद करें।" },
  hu: { title: "Mai tanulási terv", active: "Először zárj le egy hibát, majd jöhet a rövid szó -> kifejezés -> hallgatás kör.", steady: "Tartsd a ritmust: szavak bemelegítésre, kifejezések beszédhez, hallgatás és gyors ellenőrzés.", words: "5 szó az aktuális szintről példával, és gyors ismétlés csak a nehezekből.", speak: "3 hasznos kifejezés valós helyzetekhez; a legjobbat mentsd jegyzetbe.", listen: "Egy rövid hangos kifejezés: hallgasd meg, ismételd, javítsd a gyenge hangot.", repair: "Új anyag előtt zárj le egy hibát vagy helyesírási rést." },
  id: { title: "Rencana belajar hari ini", active: "Tutup satu kesalahan dulu, lalu jalankan siklus pendek kata -> frasa -> mendengar.", steady: "Jaga ritme: kata untuk pemanasan, frasa untuk berbicara, mendengar, dan cek cepat.", words: "5 kata level saat ini dengan contoh dan ulang cepat hanya yang sulit.", speak: "3 frasa berguna untuk situasi nyata; simpan yang terbaik ke catatan.", listen: "Satu frasa audio pendek: dengarkan, ulangi, lalu perbaiki bunyi terlemah.", repair: "Sebelum materi baru, tutup satu kesalahan atau celah spelling." },
  nl: { title: "Studieplan voor vandaag", active: "Sluit eerst één fout, daarna een korte cyclus woord -> zin -> luisteren.", steady: "Houd ritme: woorden om op te warmen, zinnen om te spreken, luisteren en een snelle check.", words: "5 woorden van je huidige niveau met voorbeeld en alleen de moeilijke kort herhalen.", speak: "3 nuttige zinnen voor echte situaties; bewaar de beste in notities.", listen: "Eén korte audiozin: luisteren, herhalen en de zwakste klank corrigeren.", repair: "Sluit vóór nieuw materiaal één fout of spellinggat." },
  sv: { title: "Dagens studieplan", active: "Stäng först ett misstag och kör sedan en kort cykel: ord -> fras -> lyssning.", steady: "Håll rytmen: ord för uppvärmning, fraser för tal, lyssning och en snabb kontroll.", words: "5 ord på aktuell nivå med exempel och snabb repetition bara av de svåra.", speak: "3 användbara fraser för verkliga situationer; spara den bästa i anteckningar.", listen: "En kort ljudfras: lyssna, upprepa och rätta det svagaste ljudet.", repair: "Stäng ett misstag eller stavningshål innan nytt material." },
  ta: { title: "இன்றைய கற்றல் திட்டம்", active: "முதலில் ஒரு பிழையை சரி செய்து, பிறகு சொல் -> சொற்றொடர் -> கேட்பு என்ற குறுகிய சுற்றை செய்யவும்.", steady: "ரிதத்தை வைத்திருங்கள்: சொற்கள் warm-up, சொற்றொடர்கள் பேச, கேட்பு, பிறகு விரைவு சரிபார்ப்பு.", words: "தற்போதைய நிலையின் 5 சொற்கள், எடுத்துக்காட்டுடன், கடினமானவற்றை மட்டும் விரைவாக மீள்பார்க்கவும்.", speak: "உண்மையான சூழல்களுக்கு 3 பயனுள்ள சொற்றொடர்கள்; சிறந்ததை குறிப்புகளில் சேமிக்கவும்.", listen: "ஒரு குறுகிய audio சொற்றொடர்: கேளுங்கள், மீண்டும் சொல்லுங்கள், பலவீன ஒலியை திருத்துங்கள்.", repair: "புதிய பாடத்திற்கு முன் ஒரு பிழை அல்லது spelling இடைவெளியை மூடுங்கள்." },
  te: { title: "ఈ రోజు అభ్యాస ప్రణాళిక", active: "ముందుగా ఒక తప్పును సరిచేసి, తర్వాత పదం -> పదబంధం -> వినికిడి చిన్న చక్రం చేయండి.", steady: "రిథమ్ ఉంచండి: పదాలతో warm-up, పదబంధాలతో మాట్లాడటం, వినికిడి, ఆపై త్వరిత చెక్.", words: "ప్రస్తుత స్థాయి 5 పదాలు, ఉదాహరణతో, కష్టమైనవే త్వరగా పునరావృతం.", speak: "నిజ జీవిత పరిస్థితులకు 3 ఉపయోగకరమైన పదబంధాలు; ఉత్తమదాన్ని గమనికల్లో సేవ్ చేయండి.", listen: "ఒక చిన్న audio పదబంధం: వినండి, పునరావృతం చేయండి, బలహీన ధ్వనిని సరిచేయండి.", repair: "కొత్త విషయానికి ముందు ఒక తప్పు లేదా spelling ఖాళీని మూసేయండి." },
  th: { title: "แผนเรียนวันนี้", active: "แก้ข้อผิดพลาดหนึ่งข้อก่อน แล้วทำรอบสั้น ๆ คำ -> วลี -> ฟัง", steady: "รักษาจังหวะ: คำศัพท์เพื่ออุ่นเครื่อง วลีเพื่อพูด การฟัง และเช็กอย่างรวดเร็ว", words: "คำศัพท์ระดับปัจจุบัน 5 คำ พร้อมตัวอย่าง และทบทวนเฉพาะคำที่ยาก", speak: "วลีที่ใช้ได้จริง 3 วลีสำหรับสถานการณ์จริง บันทึกวลีที่ดีที่สุดไว้", listen: "วลีเสียงสั้น 1 วลี: ฟัง พูดตาม และแก้เสียงที่ยังอ่อน", repair: "ก่อนเรียนเรื่องใหม่ ให้ปิดข้อผิดพลาดหรือช่องว่าง spelling หนึ่งจุด" },
  tl: { title: "Plano sa pag-aaral ngayon", active: "Ayusin muna ang isang mali, tapos gawin ang maikling ikot: salita -> parirala -> pakikinig.", steady: "Panatilihin ang ritmo: salita para uminit, parirala para magsalita, pakikinig, at mabilis na check.", words: "5 salita sa kasalukuyang level, may halimbawa, at mabilis na ulit para lang sa mahihirap.", speak: "3 kapaki-pakinabang na parirala para sa totoong sitwasyon; i-save ang pinakamahusay sa notes.", listen: "Isang maikling audio phrase: makinig, ulitin, at ayusin ang pinakamahinang tunog.", repair: "Bago ang bagong aralin, isara ang isang mali o spelling gap." },
  tr: { title: "Bugünkü çalışma planı", active: "Önce bir hatayı kapat, sonra kısa döngüyü yap: kelime -> ifade -> dinleme.", steady: "Ritmi koru: ısınma için kelimeler, konuşma için ifadeler, dinleme ve hızlı kontrol.", words: "Mevcut seviyeden 5 kelime, örnekle birlikte, sadece zorları hızlı tekrar.", speak: "Gerçek durumlar için 3 faydalı ifade; en iyisini notlara kaydet.", listen: "Bir kısa sesli ifade: dinle, tekrar et, zayıf sesi düzelt.", repair: "Yeni materyalden önce bir hata veya spelling boşluğunu kapat." },
  vi: { title: "Kế hoạch học hôm nay", active: "Đóng một lỗi trước, rồi làm vòng ngắn: từ -> cụm câu -> nghe.", steady: "Giữ nhịp: từ để khởi động, cụm câu để nói, nghe để luyện tai và một lần kiểm tra nhanh.", words: "5 từ ở trình độ hiện tại, có ví dụ, chỉ ôn nhanh các từ khó.", speak: "3 cụm câu hữu ích cho tình huống thật; lưu câu tốt nhất vào ghi chú.", listen: "Một câu audio ngắn: nghe, lặp lại và sửa âm yếu nhất.", repair: "Trước bài mới, đóng một lỗi hoặc khoảng trống spelling." },
};

