function applyCriticalUxCopy(code: AppLocaleCode) {
  const target = localeOverrides[code] || {};
  const payment = paymentSafetyCopy[code];
  const plan = studyPlanCopy[code];
  const passwordUx = passwordUxCopy[code];
  const paymentFields = paymentFieldCopy[code];
  const labels = {
    today: target.today || en.today,
    learnWords: target.learn_words || target.words || en.learn_words || "Words",
    practice: target.practice || en.practice,
    shadowing: target.shadowing || target.listening_phrase || en.listening_phrase,
    mistakes: target.mistakes || en.mistakes || "Mistakes",
    spelling: target.spelling || en.spelling || "Spelling",
    settings: target.settings || target.account || en.settings || "Settings",
    password: target.auth_password || en.auth_password || "Password",
    payment: target.payment_options || en.payment_options,
    network: target.network || "Network",
  };
  localeOverrides[code] = {
    ...target,
    today_plan_title: plan.title,
    today_plan_body_active: plan.active,
    today_plan_body_steady: plan.steady,
    today_plan_words_title: labels.learnWords,
    today_plan_words_body: plan.words,
    today_plan_speak_title: labels.practice,
    today_plan_speak_body: plan.speak,
    today_plan_listen_title: labels.shadowing,
    today_plan_listen_body: plan.listen,
    today_plan_repair_title: labels.mistakes,
    today_plan_repair_body: plan.repair,
    plan_words: code === "ru" ? "Словарная база" : target.plan_words || labels.learnWords,
    plan_words_count: code === "ru" ? "Одна тема: значение, пример, повтор." : `${labels.learnWords}: ${labels.today}.`,
    plan_practice: code === "ru" ? "Фразы в речь" : target.plan_practice || labels.practice,
    plan_practice_count: code === "ru" ? "Соберите полезные фразы и сохраните лучшую." : `${labels.practice}: ${labels.learnWords}.`,
    plan_listening: code === "ru" ? "Цикл аудирования" : target.plan_listening || labels.shadowing,
    plan_listening_count: code === "ru" ? "Послушать, повторить, сравнить, повторить ещё раз." : `${labels.shadowing}: ${labels.practice}.`,
    plan_roleplay: code === "ru" ? "Диалог" : target.plan_roleplay || target.roleplay || "Roleplay",
    plan_roleplay_count: code === "ru" ? "Одна практическая сцена на тему недели." : `${target.roleplay || "Roleplay"}: ${labels.practice}.`,
    plan_pronunciation: code === "ru" ? "Произношение" : target.plan_pronunciation || target.pronunciation || "Pronunciation",
    plan_pronunciation_count: code === "ru" ? "Исправьте слабые слова и один повторяющийся звук." : `${target.pronunciation || "Pronunciation"}: ${labels.shadowing}.`,
    plan_offline: code === "ru" ? "Оффлайн-ревью" : target.plan_offline || target.offline_decks || "Offline",
    plan_offline_count: code === "ru" ? "Обновите карточки и компактный TXT-пакет." : `${target.offline_decks || "Offline"}: ${labels.learnWords}.`,
    plan_dashboard: code === "ru" ? "Итоги недели" : target.plan_dashboard || target.dashboard || "Review",
    weekly_review: code === "ru" ? "Проверьте прогресс и выберите фокус следующей недели." : `${target.dashboard || "Review"}: ${labels.today}.`,
    security: code === "ru" ? "Безопасность" : target.security || labels.settings,
    change_password: passwordUx.change,
    current_password: passwordUx.current,
    new_password: passwordUx.next,
    confirm_password: passwordUx.confirm,
    password_min_hint: passwordUx.min,
    passwords_do_not_match: passwordUx.mismatch,
    passwords_match: passwordUx.match,
    save_password: passwordUx.save,
    password_changed: passwordUx.changed,
    auth_password_placeholder: passwordUx.placeholder,
    auth_password_confirm_placeholder: passwordUx.confirmPlaceholder,
    auth_password_hint: passwordUx.authHint,
    auth_password_confirm_hint: passwordUx.authConfirmHint,
    pay_stars: "Telegram Stars",
    payment_stars_instruction: payment.stars,
    payment_crypto_prepare_instruction: payment.cryptoPrepare,
    payment_crypto_instruction: payment.crypto,
    payment_usdt_trc20_instruction: payment.trc20,
    shown_amount: payment.shownAmount,
    payment_requisites: code === "ru" ? "Реквизиты оплаты" : target.payment_requisites || labels.payment,
    check_payment: code === "ru" ? "Проверить оплату" : target.check_payment || labels.payment,
    specified_network: code === "ru" ? "указанная сеть" : target.specified_network || labels.network,
    network: paymentFields.network,
    comment: paymentFields.comment,
    expires_at: paymentFields.expires,
    tx_hash: paymentFields.tx,
  };
}

appLocaleCodes.forEach((code) => applyCriticalUxCopy(code));

