let cp1251ReverseMap: Map<string, number> | null = null;

function getCp1251ReverseMap() {
  if (cp1251ReverseMap) return cp1251ReverseMap;
  cp1251ReverseMap = new Map<string, number>();
  if (typeof TextDecoder === "undefined") return cp1251ReverseMap;
  const decoder = new TextDecoder("windows-1251");
  for (let byte = 0; byte < 256; byte += 1) {
    cp1251ReverseMap.set(decoder.decode(new Uint8Array([byte])), byte);
  }
  return cp1251ReverseMap;
}

function mojibakeScore(value: string) {
  const suspicious = new RegExp(
    "[\\u0420\\u0421\\u00d0\\u00d1\\u00c2\\u00c3\\u0403\\u040c\\u040b\\u040f\\u0459\\u045a\\u045c\\u045b\\u045f\\u0457\\ufffd]",
    "g",
  );
  return (value.match(suspicious) || []).length;
}

const fallbackLeakAllowedKeys = new Set([
  "ai_router",
  "app_guide_page_label",
  "guide",
  "pay_stars",
  "tutor_completed_lessons_body",
  "tutor_completed_lessons_empty",
  "tutor_reward_saved",
]);

function isLikelyFallbackLeak(locale: AppLocaleCode, key: string, value: string, fallback?: string) {
  if (locale === "en") return false;
  if (key.startsWith("app_guide_")) return false;
  if (fallbackLeakAllowedKeys.has(key)) return false;
  if (key === "sample_phrase") return false;
  if (key === "skip") return false;
  const cleaned = cleanAppText(value).trim();
  if (!cleaned) return true;
  if (en[key] && cleaned === cleanAppText(en[key]).trim()) return true;
  if (fallback && cleaned === cleanAppText(fallback).trim() && /[A-Za-z]/.test(cleaned)) return true;
  if (fallback && locale !== "ru" && cleaned === cleanAppText(fallback).trim() && /[А-Яа-яЁё]/.test(cleaned)) return true;
  if (/Ð|Ñ|Гђ|Г‘|б»|бє|бї|аё|а№|а¤|аҐ|а¦|а§|а®|а°/u.test(cleaned)) return true;
  if (/^[^\s:]+:\s*[a-z0-9_ -]+$/i.test(cleaned) || /^(Section|Раздел|Mục):\s*/i.test(cleaned)) return true;
  return false;
}

function decodeMojibakeRun(run: string) {
  const map = getCp1251ReverseMap();
  if (!map.size || typeof TextDecoder === "undefined") return run;
  const bytes: number[] = [];
  for (const char of run) {
    const byte = char.charCodeAt(0) <= 0x7f ? char.charCodeAt(0) : map.get(char);
    if (byte === undefined) return run;
    bytes.push(byte);
  }
  try {
    const decoded = new TextDecoder("utf-8", { fatal: false }).decode(new Uint8Array(bytes));
    if (!decoded || decoded.includes("\uFFFD")) return run;
    if (mojibakeScore(decoded) < mojibakeScore(run)) return decoded;
  } catch {
    return run;
  }
  return run;
}

export function cleanAppText(value: unknown): string {
  const text = String(value ?? "");
  if (!text) return "";
  const mojibakeLead = "[\\u0420\\u0421]";
  const mojibakeTail = "[\\u0080-\\u04ff\\u2010-\\u214f]";
  const pairRun = new RegExp(`(?:${mojibakeLead}${mojibakeTail}){2,}`, "g");
  const singlePair = new RegExp(`${mojibakeLead}${mojibakeTail}`, "g");
  const repairedPairs = text
    .replace(pairRun, (run) => decodeMojibakeRun(run))
    .replace(singlePair, (run) => decodeMojibakeRun(run));
  return repairedPairs
    .replace(/[\u0000-\u007f\u0080-\u024f\u0400-\u04ff\u0530-\u058f\u10a0-\u10ff\u2010-\u214f]+/g, (run) =>
      mojibakeScore(run) ? decodeMojibakeRun(run) : run,
    )
    .replace(/\u0432\u2020\u2019/g, "→")
    .replace(/\u0412\u00b7/g, "·");
}

export function normalizeAppLocale(code: string | undefined | null): AppLocaleCode {
  const normalized = String(code || "").toLowerCase().trim();
  return appLocaleCodes.includes(normalized as AppLocaleCode) ? (normalized as AppLocaleCode) : "ru";
}

export function appCopy(code: string | undefined | null, key: string, fallback?: string): string {
  const locale = normalizeAppLocale(code);
  const raw = localeOverrides[locale]?.[key] || en[key] || fallback || key;
  const cleaned = cleanAppText(raw);
  const localized = isLikelyFallbackLeak(locale, key, cleaned, fallback) ? cleanAppText(localizedFallbackForEnglishCopy(locale, key)) : cleaned;
  return normalizePremiumAndTutorCopy(locale, localized);
}

function normalizePremiumAndTutorCopy(locale: AppLocaleCode, value: string) {
  const terms = premiumAndTutorTerms(locale);
  const replacements: Array<[string, string]> = [
    ["Try the path", terms.starter],
    ["Попробовать маршрут", terms.starter],
    ["AI Tutor " + "guided lessons", terms.aiLessons],
    ["guided AI " + "lessons", terms.aiLessons],
    ["guided " + "lessons", terms.aiLessons],
    ["AI Tutor and guided AI " + "lessons", `AI Tutor and ${terms.aiLessons}`],
    ["listening, pronunciation", terms.listeningPronunciation],
    ["Listening and " + "pronunciation", terms.listeningPronunciation],
    ["Listening и " + "pronunciation", terms.listeningPronunciation],
    ["voice " + "checks and photo " + "tools", terms.voicePhoto],
    ["voice " + "checks", terms.voiceReview],
    ["photo " + "tools", terms.imageTools],
    ["voice/" + "pronunciation", terms.voicePronunciation],
    ["voice/" + "photo-context", terms.voicePhotoContext],
    ["heavy daily " + "learning", terms.heavyStudy],
    ["Write your own answer " + "using the lesson words.", terms.writingInstruction],
    ["Write at least two complete sentences " + "before moving on.", terms.twoSentences],
    ["You finished the guided " + "sequence: words, pattern, answer, writing, listening, pronunciation, dialogue, final word check, assessment, and review.", terms.completeBody],
    ["Раздел", ""],
  ];
  let out = value;
  for (const [from, to] of replacements) {
    out = out.split(from).join(to);
  }
  return out.replace(/\s{2,}/g, " ").trim();
}

function premiumAndTutorTerms(locale: AppLocaleCode) {
  if (locale === "ru") {
    return {
      starter: "Начальный",
      aiLessons: "AI-уроки",
      listeningPronunciation: "аудирование, произношение",
      voicePhoto: "проверки голоса и фото-инструменты",
      voiceReview: "проверки голоса",
      imageTools: "фото-инструменты",
      voicePronunciation: "практика голоса и произношения",
      voicePhotoContext: "практика по голосу или фото",
      heavyStudy: "плотная ежедневная учеба",
      writingInstruction: "Напишите 2-3 предложения на языке урока по теме истории и используйте минимум 3 новых слова.",
      twoSentences: "Напишите минимум два полных предложения, чтобы продолжить.",
      completeBody: "Урок завершён: история, пересказ, вопросы, слова, письмо, разбор и повторение.",
    };
  }
  return {
    starter: "Starter",
    aiLessons: "AI-guided tutor lessons",
    listeningPronunciation: "listening practice and pronunciation scoring",
    voicePhoto: "voice review and image tools",
    voiceReview: "voice review",
    imageTools: "image tools",
    voicePronunciation: "voice and pronunciation",
    voicePhotoContext: "voice or image-context",
    heavyStudy: "dense daily study",
    writingInstruction: "Write 2-3 target-language sentences about the story and use at least 3 lesson words.",
    twoSentences: "Add at least two complete sentences to continue.",
    completeBody: "Lesson finished: story, retell, questions, words, writing, assessment, and review.",
  };
}

export function translateViewDetails(view: ViewId, copy: (key: string, fallback: string) => string) {
  const key = view.replace("-", "_");
  return {
    kicker: copy(`view_${key}_kicker`, en[`view_${key}_kicker`] || ""),
    title: copy(`view_${key}_title`, en[`view_${key}_title`] || view),
    subtitle: copy(`view_${key}_subtitle`, en[`view_${key}_subtitle`] || ""),
    action: en[`view_${key}_action`] ? copy(`view_${key}_action`, en[`view_${key}_action`]) : undefined,
  };
}

export function appNavDescription(view: ViewId, copy: (key: string, fallback: string) => string, fallback: string) {
  return copy(`nav_${view.replace("-", "_")}_desc`, fallback);
}
